import("./tasks/drone-hard/task.mjs").then(async ({ TASK, GATES, PAD, random, trialParameters }) => {
  const { initialState } = await import("./tasks/drone-hard/sim.mjs");
  const makeController = (await import("/workspace/controller.js")).default;
  const clamp = (v, lo, hi) => Math.max(lo, Math.min(hi, v));
  const norm = (v) => Math.hypot(v.x, v.y, v.z);
  const copy = (v) => ({ ...v });
  const MOTOR_X = [-1, 1, 1, -1], MOTOR_Z = [-1, -1, 1, 1], SPIN = [1, -1, 1, -1];
  function runOne(seed) {
    const parameters = trialParameters(seed), state = initialState(parameters), rng = random((seed ^ 0xa5a5a5a5) >>> 0);
    const ctrl = makeController();
    for (let step = 0; step < 1500 && !state.reason; step++) {
      const noise = (n) => (rng() + rng() + rng() - 1.5) * n;
      const vector = (v, n) => Object.fromEntries(Object.entries(v).map(([k, val]) => [k, val + noise(n)]));
      const obs = {
        t: +state.t.toFixed(4), pos: vector(state.pos, TASK.positionNoise), vel: vector(state.vel, TASK.velocityNoise),
        att: vector(state.att, TASK.attitudeNoise), rates: vector(state.rates, TASK.rateNoise),
        gateIndex: state.gateIndex,
        nextGate: state.gateIndex < 3 ? { centre: copy(GATES[state.gateIndex].centre), normal: {x:1,y:0,z:0} } : null,
        pad: { centre: copy(PAD.centre) }
      };
      const raw = ctrl.step(obs);
      const action = { thrust: clamp(raw.thrust, 0, 1), roll: clamp(raw.roll, -0.6, 0.6), pitch: clamp(raw.pitch, -0.6, 0.6), yawRate: clamp(raw.yawRate, -2, 2) };
      for (let sub = 0; sub < 2 && !state.reason; sub++) {
        const dt = 0.005, old = copy(state.pos), { att, rates } = state;
        const inertia = TASK.inertia * parameters.mass / TASK.baseMass;
        const torque = {};
